@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + AvailableStorageSpace : int
  + CurrentLoadWeight : double
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : DayOfWeek[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class H2SEmployee {
  + FirstName : string
  + LastName : string
  + RFIDDevice : RFIDDevice
}

enum DayOfWeek {
  Monday
  Tuesday
  Wednesday
  Thursday
  Friday
}

class PickupRoute {
  + RouteNumber : int
  + Days : DayOfWeek[]
}

class ScheduledPickup {
  + PickupTime : time
  + Resident : Resident
  + Vehicle : PickupVehicle
  + Driver : VolunteerDriver
}

class RFIDDevice {}

class Category {
  + Name : string
}

class SecondHandArticle {
  + Description : string
  + QualityStatus : string
  + Category : Category
  + RFIDTag : RFIDDevice
}

class Client {
  + Name : string
  + Address : string
  + NeededCategories : Category[]
}

class DeliveryRequest {
  + Article : SecondHandArticle
  + Client : Client
}

Resident "1" -- "*" ScheduledPickup
VolunteerDriver "0..*" -- "1" PickupRoute
PickupVehicle "0..*" -- "1" PickupRoute
PickupVehicle "1" -- "*" ScheduledPickup
DistributionCenter "1" -- "*" SecondHandArticle : receives
FoodBank "1" -- "*" SecondHandArticle : receives
H2SEmployee "1" -- "*" SecondHandArticle : examines
H2SEmployee "0..*" -- "1" Client : calls
Client "0..*" -- "1" DeliveryRequest

@enduml

